// The commander shape in miniature: a getter/setter method whose declared
// OVERLOADS (index.d.ts) say `name(): string` / `name(v): this`, while the
// JS body infers the union `string | Chainy`. --npm-static projects these
// safe overload groups onto this exported runtime class before TS 7 parses
// it, preserving precise calls while compiling the body below.
'use strict';

class Chainy {
  constructor() {
    this._name = '';
    this._tag = '';
  }
  name(v) {
    if (v === undefined) return this._name;
    this._name = v;
    return this;
  }
  tag(v) {
    if (v === undefined) return this._tag;
    this._tag = v;
    return this;
  }
  render() {
    return this._name + '#' + this._tag;
  }
}

module.exports = { Chainy };
